<?php session_start();require_once __DIR__.'/../../src/db.php';require_once __DIR__.'/../../src/upload.php';require_once __DIR__.'/../../src/tiles.php';if(!($_SESSION['admin']??false)){header('Location:/admin/');exit;}$err='';$editId=(int)($_GET['id']??0);$existing=null;if($editId){$q=db()->prepare('SELECT * FROM panoramas WHERE id=?');$q->execute([$editId]);$existing=$q->fetch();if(!$existing){http_response_code(404);exit('Not found');}}$savedEffects=json_decode($existing['effects']??'{}',true)?:[];if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!$existing&&(!isset($_FILES['image'])||$_FILES['image']['error']))throw new RuntimeException('Выберите изображение');$f=$_FILES['image'];$projection=in_array($_POST['projection']??'', ['flat','180','360'],true)?$_POST['projection']:'360';$stereo=in_array($_POST['stereo']??'', ['mono','sbs','tb'],true)?$_POST['stereo']:'mono';$name=$existing?basename($existing['image']):'';if(($f['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_OK){$name=storeUploadedImage($f,UPLOAD_DIR);if($projection==='360'&&$stereo==='mono')buildPanoramaTiles(UPLOAD_DIR.'/'.$name,__DIR__.'/../tiles/'.pathinfo($name,PATHINFO_FILENAME));}$title=trim($_POST['title']);$slug=preg_replace('/[^a-z0-9]+/','-',strtolower($_POST['slug']?:bin2hex(random_bytes(4))));$effects=['rotation'=>isset($_POST['rotation']),'rotationSpeed'=>max(0,min(10,(float)($_POST['rotationSpeed']??1))),'particles'=>in_array($_POST['particles']??'none',['none','rain','snow','leaves'],true)?$_POST['particles']:'none','density'=>max(0,min(100,(int)($_POST['density']??35))),'speed'=>max(.1,min(4,(float)($_POST['speed']??1))),'wind'=>max(-8,min(8,(float)($_POST['wind']??0))),'opacity'=>max(10,min(100,(int)($_POST['opacity']??80)))];$values=[$title,$slug,trim($_POST['description']),'/uploads/'.$name,$projection,$stereo,isset($_POST['published'])?1:0,json_encode($effects)];if($existing){$values[]=$editId;$q=db()->prepare("UPDATE panoramas SET title=?,slug=?,description=?,image=?,projection=?,stereo=?,published=?,effects=? WHERE id=?");}else{$q=db()->prepare("INSERT INTO panoramas(title,slug,description,image,projection,stereo,published,effects) VALUES(?,?,?,?,?,?,?,?)");}$q->execute($values);header('Location:/admin/');exit;}catch(Throwable $e){$err=$e->getMessage();}}?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="/assets/admin.css"></head><body><aside><div class="logo">MINI<span>VR</span></div><a href="/admin/">← Материалы</a></aside><main><header><div><small>NEW VR ASSET</small><h1><?= $existing ? "Настройки панорамы" : "Новый материал" ?></h1></div></header><?php if($err):?><div class="error"><?=htmlspecialchars($err)?></div><?php endif;?><form class="editor" method="post" enctype="multipart/form-data"><label>Название<input name="title" value="<?=htmlspecialchars($existing['title']??'')?>" required placeholder="Главный зал"></label><label>Slug<input name="slug" value="<?=htmlspecialchars($existing['slug']??'')?>" placeholder="main-hall"></label><label>Проекция<select name="projection"><option value="360" <?=($existing['projection']??'360')==='360'?'selected':''?>>360° equirectangular</option><option value="180" <?=($existing['projection']??'360')==='180'?'selected':''?>>180° panorama</option><option value="flat" <?=($existing['projection']??'360')==='flat'?'selected':''?>>Плоское изображение</option></select></label><label>Стерео<select name="stereo"><option value="mono" <?=($existing['stereo']??'mono')==='mono'?'selected':''?>>Mono</option><option value="sbs" <?=($existing['stereo']??'mono')==='sbs'?'selected':''?>>Stereo SBS — Left | Right</option><option value="tb" <?=($existing['stereo']??'mono')==='tb'?'selected':''?>>Stereo Top / Bottom</option></select></label><label>Описание<textarea name="description" rows="5"><?=htmlspecialchars($existing['description']??'')?></textarea></label><label class="drop">VR IMAGE ASSET<input type="file" name="image" accept="image/jpeg,image/png,image/webp" <?= $existing ? "" : "required" ?>><span>JPG / WEBP / PNG • mono / SBS / Top-Bottom</span></label><fieldset style="border:1px solid #36738d;border-radius:14px;padding:16px;margin:14px 0"><legend>Эффекты панорамы</legend>
<label class="check"><input type="checkbox" name="rotation" value="1" <?=!empty($savedEffects['rotation'])?'checked':''?>> Автоматическое вращение</label>
<label>Вращение, градусов/сек <input type="number" name="rotationSpeed" min="0" max="10" step=".1" value="<?=htmlspecialchars((string)($savedEffects['rotationSpeed']??1))?>"></label>
<label>Эффект частиц <select name="particles"><?php foreach(['none'=>'Нет','rain'=>'Дождь','snow'=>'Снег','leaves'=>'Листья'] as $k=>$v):?><option value="<?=$k?>" <?=($savedEffects['particles']??'none')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label>
<label>Плотность (0–100) <input type="number" name="density" min="0" max="100" value="<?=htmlspecialchars((string)($savedEffects['density']??35))?>"></label>
